import { NgFor } from '@angular/common';
import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  EventEmitter,
  Input,
  OnInit,
  Output,
  ViewEncapsulation,
  inject,
} from '@angular/core';
import { TranslocoModule } from '@jsverse/transloco';
import { QDestroyService } from '@questrade/allspark-angular-components/core/services';
import {
  ALLSPARK_SCOPE,
  MISSING_KEY_HANDLER,
} from '@questrade/allspark-angular-components/transloco';
import { takeUntil } from 'rxjs';
import { DateAdapter } from '../../date-adapter';
import { DatepickerService } from '../../datepicker.service';
import { DateRange } from '../../daterange';

import { QCalendarLocation } from '../../types/calendar-location.type';
import {
  QCalendarBodyComponent,
  QCalendarUserEvent,
} from '../calendar-body/calendar-body.component';
import { QCalendarCell } from '../calendar-body/calendar-cell';

const DAYS_PER_WEEK = 7;

@Component({
  selector: 'q-month-view',
  templateUrl: './month-view.component.html',
  styleUrls: ['./month-view.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  imports: [NgFor, TranslocoModule, QCalendarBodyComponent],
  providers: [QDestroyService, MISSING_KEY_HANDLER, ALLSPARK_SCOPE],
})
export class QMonthViewComponent implements OnInit {
  @Output() readonly daySelected = new EventEmitter<QCalendarUserEvent<Date | null>>();
  @Output() readonly activeDateChange = new EventEmitter<Date>();

  @Input() calendarLocation: QCalendarLocation = 'left';
  @Input() monthViewId = '';
  @Input() get minDate(): Date | null {
    return this._minDate;
  }
  set minDate(value: Date | null) {
    this._minDate = value;
    this._createWeekCells();
  }

  @Input() get maxDate(): Date | null {
    return this._maxDate;
  }
  set maxDate(value: Date | null) {
    this._maxDate = value;
    this._createWeekCells();
  }

  @Input() get activeDate(): Date {
    return this._activeDate;
  }
  set activeDate(value: Date) {
    if (value) {
      const oldActiveDate = this._activeDate;

      this._activeDate = value;

      if (!this._hasSameMonthAndYear(oldActiveDate, this._activeDate)) {
        this._init();
      }
    }
  }

  @Input() get selected(): DateRange | Date | null {
    return this._selected;
  }
  set selected(value: DateRange | Date | null) {
    this._selected = value;
    this._setRanges(this._selected);
  }

  _weeks: QCalendarCell[][] = [];
  _firstWeekOffset = 0;
  _todayDate: number | null = null;
  _rangeStart: number | null = null;
  _rangeEnd: number | null = null;
  _isRange = false;
  _disableWeekends = false;
  _disabledDates: Date[] = [];

  private _minDate: Date | null = null;
  private _maxDate: Date | null = null;
  private _activeDate: Date;
  private _selected: DateRange | Date | null = null;
  private readonly _datepickerService = inject(DatepickerService);
  private readonly _destroy$ = inject(QDestroyService);
  private _dateAdapter = inject(DateAdapter);
  private readonly _changeDetectorRef = inject(ChangeDetectorRef);

  constructor() {
    this._activeDate = new Date();
  }

  ngOnInit(): void {
    this._init();
    this._datepickerService.disableWeekends$
      .pipe(takeUntil(this._destroy$))
      .subscribe((disableWeekends) => {
        this._disableWeekends = disableWeekends;
        this._createWeekCells();
        this._changeDetectorRef.markForCheck();
      });

    this._datepickerService.disabledDates$
      .pipe(takeUntil(this._destroy$))
      .subscribe((disabledDates) => {
        this._disabledDates = disabledDates;
        this._createWeekCells();
        this._changeDetectorRef.markForCheck();
      });
  }

  _dateSelected(event: QCalendarUserEvent<number>): void {
    const date = event.value;
    const selectedDate = new Date(
      this.activeDate.getFullYear(),
      this.activeDate.getMonth(),
      date,
      0,
      0,
      0,
    );

    this.daySelected.emit({ value: selectedDate, event: event.event });

    this._datepickerService.updatePreview(new DateRange(null, null));
    this._changeDetectorRef.markForCheck();
  }

  _isWeekend(weekDay: string): boolean {
    const weekend = ['sunday', 'saturday'];
    return weekend.includes(weekDay);
  }

  get _weekDays(): string[] {
    return ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];
  }

  private _init(): void {
    this._setRanges(this.selected);
    this._todayDate = new Date(new Date().setHours(0, 0, 0, 0)).getTime();
    const firstOfMonth = new Date(this.activeDate.getFullYear(), this.activeDate.getMonth(), 1);

    this._firstWeekOffset = (DAYS_PER_WEEK + firstOfMonth.getDay()) % DAYS_PER_WEEK;

    this._createWeekCells();
    this._changeDetectorRef.markForCheck();
  }

  private _createWeekCells(): void {
    const daysInMonth = this._dateAdapter.getNumDaysInMonth(this.activeDate);

    this._weeks = [[]];

    for (let i = 0, cell = this._firstWeekOffset; i < daysInMonth; i++, cell++) {
      if (cell === DAYS_PER_WEEK) {
        this._weeks.push([]);
        cell = 0;
      }

      const date = new Date(this.activeDate.getFullYear(), this.activeDate.getMonth(), i + 1);
      const isEnabled = this._shouldEnableDate(date);

      this._weeks[this._weeks.length - 1].push(
        new QCalendarCell(i + 1, String(i + 1), isEnabled, date),
      );
    }
  }

  private _setRanges(selectedValue: DateRange | Date | null): void {
    if (selectedValue instanceof DateRange) {
      this._rangeStart = selectedValue.start?.getTime() || null;
      this._rangeEnd = selectedValue.end?.getTime() || null;
      this._isRange = true;
    } else {
      this._rangeStart = this._rangeEnd = selectedValue?.getTime() || null;
      this._isRange = false;
    }
  }

  private _hasSameMonthAndYear(d1: Date | null, d2: Date | null): boolean {
    return !!(d1 && d2 && d1.getMonth() === d2.getMonth() && d1.getFullYear() === d2.getFullYear());
  }

  private _shouldEnableDate(date: Date): boolean {
    return (
      !!date &&
      (!this.minDate || this._dateAdapter.compareDate(date, this.minDate) >= 0) &&
      (!this.maxDate || this._dateAdapter.compareDate(date, this.maxDate) <= 0) &&
      !(this._isDisabledWeekend(date) || this._isDisabledDate(date))
    );
  }

  private _isDisabledDate(date: Date): boolean {
    return !!this._disabledDates?.some(
      (disableDate: Date) => !this._dateAdapter.compareDate(disableDate, date),
    );
  }

  private _isDisabledWeekend(date: Date): boolean {
    return this._disableWeekends && this._isWeekend(this._weekDays[date.getDay()]);
  }
}
