import { A11yModule } from '@angular/cdk/a11y';
import { BreakpointObserver, BreakpointState } from '@angular/cdk/layout';
import { CdkVirtualScrollViewport, ScrollingModule } from '@angular/cdk/scrolling';
import { NgIf } from '@angular/common';
import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  EventEmitter,
  HostBinding,
  HostListener,
  Input,
  OnInit,
  Output,
  ViewChild,
  ViewEncapsulation,
  booleanAttribute,
  effect,
  forwardRef,
  inject,
  numberAttribute,
  signal,
} from '@angular/core';
import { ControlValueAccessor, NG_VALUE_ACCESSOR } from '@angular/forms';
import { TranslocoModule, TranslocoService } from '@jsverse/transloco';
import { QButtonComponent } from '@questrade/allspark-angular-components/button';
import { QScrollShadowDirective } from '@questrade/allspark-angular-components/core/directives';
import { QDestroyService } from '@questrade/allspark-angular-components/core/services';
import { voidFn } from '@questrade/allspark-angular-components/core/utils';
import {
  ALLSPARK_SCOPE,
  MISSING_KEY_HANDLER,
} from '@questrade/allspark-angular-components/transloco';
import { takeUntil } from 'rxjs';
import { QCalendarComponent } from './calendar/calendar.component';
import { DateAdapter } from './date-adapter';
import { DatepickerService } from './datepicker.service';
import { DateRange } from './daterange';
import { QCalendarView } from './types/calendar-view.type';

@Component({
  selector: 'q-datepicker',
  templateUrl: './datepicker.component.html',
  styleUrls: ['./datepicker.component.scss'],
  imports: [
    NgIf,
    TranslocoModule,
    QButtonComponent,
    QCalendarComponent,
    A11yModule,
    ScrollingModule,
    QScrollShadowDirective,
  ],
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => QDatePickerComponent),
      multi: true,
    },
    DatepickerService,
    QDestroyService,
    MISSING_KEY_HANDLER,
    ALLSPARK_SCOPE,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
})
export class QDatePickerComponent implements OnInit, ControlValueAccessor {
  @Output() readonly clearButtonClicked = new EventEmitter<void>();
  @Output() readonly doneButtonClicked = new EventEmitter<void>();
  @Output() readonly valueChanged = new EventEmitter<Date | DateRange | null>();
  @Output() readonly viewChanged = new EventEmitter<QCalendarView>(true);

  @Input() startAt: Date | null = null;
  @Input({ transform: booleanAttribute }) displayDoneButton = true;
  @Input({ transform: booleanAttribute }) displayClearButton = true;
  @Input({ transform: booleanAttribute }) displaySingleCalendar = false;
  @Input({ transform: numberAttribute }) mobileBreakpoint = 599;
  @Input('aria-label') ariaLabel: string | null = null;
  @Input() clearButtonAriaLabel = '';
  @Input() doneButtonAriaLabel = '';
  @Input() previousMonthButtonAriaLabel = '';
  @Input() nextMonthButtonAriaLabel = '';
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-datepicker';

  @Input({ transform: booleanAttribute }) get disableWeekends(): boolean {
    return this._disableWeekends;
  }
  set disableWeekends(value: boolean) {
    this._disableWeekends = value;
    this._datepickerService.updateDisableWeekends(value);
  }

  @Input() get disabledDates(): Date[] {
    return this._disabledDates;
  }
  set disabledDates(value: Date[]) {
    this._disabledDates = value;
    this._datepickerService.updateDisabledDates(value);
  }

  @Input() get isRangePicker(): boolean {
    return this._isRangePicker;
  }
  set isRangePicker(value: boolean) {
    this._isRangePicker = value;
    this._updateSelection();
  }

  @Input() get displayLastDisabledMonth(): boolean {
    return this._displayLastDisabledMonth;
  }
  set displayLastDisabledMonth(value: boolean) {
    if (this._displayLastDisabledMonth !== value) {
      this._displayLastDisabledMonth = value;
      this._init();
    }
  }

  @Input() get minDate(): Date | null {
    return this._minDate;
  }
  set minDate(value: Date | null) {
    if (!this._dateAdapter.sameDate(value, this._minDate)) {
      this._minDate = value;
    }
  }

  @Input() get maxDate(): Date | null {
    return this._maxDate;
  }
  set maxDate(value: Date | null) {
    if (!this._dateAdapter.sameDate(value, this._maxDate)) {
      this._maxDate = value;
    }
  }

  set isMobile(value: boolean) {
    if (this._isMobile !== value) {
      this._isMobile = value;
      this._isReadyToScroll.set(false);
      this._init();
    }
  }
  get isMobile(): boolean {
    return this._isMobile;
  }

  @HostBinding('class') hostClass = 'q-datepicker';
  @HostBinding('attr.aria-label') ariaLabelAttr: string | null = null;
  @HostBinding('class.q-datepicker-full') get isFullCalendarView(): boolean {
    return (
      !this.isMobile &&
      !this.displaySingleCalendar &&
      this._currentViewFirstCalendar !== 'multi-year'
    );
  }

  @ViewChild(CdkVirtualScrollViewport) viewport?: CdkVirtualScrollViewport;

  @HostListener('blur') _onBlur = (): void => this._onTouched();

  _activeDateFirstCalendar: Date | null = null;
  _activeDateSecondCalendar: Date | null = null;
  _selection: Date | DateRange | null = null;
  _currentViewFirstCalendar: QCalendarView = 'month';
  _currentViewSecondCalendar: QCalendarView = 'month';
  _calendarList: { month: number; year: number }[] = [];
  _isMobile = false;
  _isReadyToScroll = signal(false);
  _onChangeFn: (_: Date | DateRange | null) => void = voidFn;
  _onTouched: () => void = voidFn;
  readonly _datepickerService = inject(DatepickerService);

  private _controlAccessorValue: Date | DateRange | null = null;
  private _isRangePicker = false;
  private _displayLastDisabledMonth = false;
  private _minDate: Date | null = null;
  private _maxDate: Date | null = null;
  private _disableWeekends = false;
  private _disabledDates: Date[] = [];
  private readonly _destroy$ = inject(QDestroyService);
  private readonly _dateAdapter = inject(DateAdapter);
  private readonly _breakpointObserver = inject(BreakpointObserver);
  private readonly _cdr = inject(ChangeDetectorRef);
  private readonly _translocoService = inject(TranslocoService);

  constructor() {
    effect(() => {
      if (this._isReadyToScroll()) this._init();
    });
  }

  ngOnInit(): void {
    this._breakpointObserver
      .observe([`(max-width: ${this.mobileBreakpoint}px)`])
      .pipe(takeUntil(this._destroy$))
      .subscribe((result: BreakpointState) => {
        this.isMobile = result.matches;
        this._cdr.markForCheck();
      });

    this._calendarList = this._generateCalendarList();
    this._init();

    this._datepickerService.selection$
      .pipe(takeUntil(this._destroy$))
      .subscribe((selection: Date | DateRange | null) => {
        this._selection = selection;
      });

    this.ariaLabelAttr = this.ariaLabel;

    this._translocoService
      .selectTranslate('datepicker.chooseDate', {}, 'allspark')
      .pipe(takeUntil(this._destroy$))
      .subscribe((translation) => {
        this.ariaLabelAttr = this.ariaLabel || translation;
      });
  }

  createDate(year: number, month: number, day: number): Date {
    return new Date(year, month, day);
  }

  private _generateCalendarList(): { month: number; year: number }[] {
    if (this.minDate && this.maxDate) {
      return this._dateAdapter.getMonthsInRange(this.minDate, this.maxDate);
    } else {
      const now = new Date();
      const min = new Date(now.getFullYear(), now.getMonth() - 1200, 1);
      const max = new Date(now.getFullYear(), now.getMonth() + 1200, 1);
      return this._dateAdapter.getMonthsInRange(min, max);
    }
  }

  _onScrolledIndexChange(): void {
    if (!this._isReadyToScroll()) this._isReadyToScroll.set(true);
  }

  _addCalendar(): void {
    const last = this._calendarList[this._calendarList.length - 1];

    let nextMonth = last.month + 1;
    let nextYear = last.year;
    if (nextMonth > 11) {
      nextMonth = 0;
      nextYear++;
    }
    this._calendarList.push({ month: nextMonth, year: nextYear });
    this.viewport?.checkViewportSize();
  }

  _scrollToMonthYear(month: number, year: number): void {
    const index = this._calendarList.findIndex((cal) => cal.month === month && cal.year === year);
    if (index >= 0 && this.viewport) {
      this.viewport.scrollToIndex(index, 'auto');
    }
  }

  _yearSelected(date: Date): void {
    this._scrollToMonthYear(date.getMonth(), date.getFullYear());
  }

  _onMonthSelected(date: Date): void {
    this._scrollToMonthYear(date.getMonth(), date.getFullYear());
  }

  _onClearClick(): void {
    this._clearSelection();
    this.clearButtonClicked.emit();
  }

  _clearSelection(): void {
    if (
      this._controlAccessorValue &&
      this._dateAdapter.isValidDateObject(this._controlAccessorValue) &&
      !this._dateAdapter.sameDateObject(
        this._controlAccessorValue,
        this._datepickerService.selection,
      )
    ) {
      this._datepickerService.updateSelection(this._controlAccessorValue);

      if (!this.displayDoneButton) {
        this._updateSelectedValue();
      }

      this._init();
    } else {
      this._updateSelection(null);
      this._onSelectedChange(null);
      this._controlAccessorValue = null;

      this._setDatepickerVisibilityToDate();
    }
  }

  _init(): void {
    this._updateSelection(this._datepickerService.selectedValue);
    if (this._currentViewFirstCalendar === 'multi-year') return;

    if (
      this._isRange() &&
      this._dateAdapter.isValid((this._datepickerService.selectedValue as DateRange)?.start)
    ) {
      const leftCalendarActiveDate = (this._datepickerService.selectedValue as DateRange)?.start;
      this._setDatepickerVisibilityToDate(leftCalendarActiveDate);
    } else if (
      !this._isRange() &&
      this._dateAdapter.isValid(this._datepickerService.selectedValue as Date)
    ) {
      const leftCalendarActiveDate = this._datepickerService.selectedValue as Date;
      this._setDatepickerVisibilityToDate(leftCalendarActiveDate);
    } else {
      this._setDatepickerVisibilityToDate();
    }
  }

  _reset(): void {
    this._currentViewFirstCalendar = this._currentViewSecondCalendar = 'month';
    this._activeDateFirstCalendar = null;
    this._activeDateSecondCalendar = null;
    this._clearSelection();
    this._datepickerService.updateSelectedValue(null);
    this._cdr.markForCheck();
    this._init();
  }

  _onMonthChangedByArrow(delta: number): void {
    this._datepickerService.shiftActiveDatesByDelta(delta);
  }

  _onDoneClick(): void {
    this._updateSelectedValue();
    this.doneButtonClicked.emit();
  }

  _isRange(): boolean {
    return this._selection instanceof DateRange;
  }

  _getSelected(): Date | DateRange | null {
    return this._selection;
  }

  _onYearSelected(date: Date | null): void {
    if (this._currentViewFirstCalendar !== 'multi-year') return;

    this._datepickerService.updateSelection(date);

    if (!this.displayDoneButton) {
      this._updateSelectedValue();
    }
  }

  _onSelectedChange(date: Date | null): void {
    if (this._isRange()) {
      let { start, end } = this._selection as DateRange;

      if (start === null) {
        start = date;
      } else if (end === null && date && this._dateAdapter.compareDate(date, start) >= 0) {
        end = date;
      } else if (date) {
        start = date;
        end = null;
      }

      this._datepickerService.updateSelection(new DateRange(start, end));
    } else {
      this._datepickerService.updateSelection(date);
    }

    if (!this.displayDoneButton) {
      this._updateSelectedValue();
    }
  }

  _viewChanged(view: QCalendarView, source: string, calendar?: QCalendarComponent): void {
    if (source === 'firstCalendar') {
      this._currentViewFirstCalendar = view;
    } else if (source === 'secondCalendar') {
      this._currentViewSecondCalendar = view;
    }

    if (view === 'month') {
      calendar?._setCalendarHeaderComponentFocus();
    }

    this.viewChanged.emit(view);
  }

  _showFirstCalendar(): boolean {
    return this._currentViewSecondCalendar === 'month';
  }

  _showSecondCalendar(): boolean {
    return (
      !this.isMobile && !this.displaySingleCalendar && this._currentViewFirstCalendar === 'month'
    );
  }

  _showFooter(): boolean {
    const anyButtonEnabled = this.displayClearButton || this.displayDoneButton;
    return (
      this._currentViewFirstCalendar === 'month' &&
      this._currentViewSecondCalendar === 'month' &&
      anyButtonEnabled
    );
  }

  // #region ControlValueAccessor implementation

  /** @hidden */
  writeValue(value: DateRange | Date): void {
    const oldSelection = this._selection;
    const sameValueAndOldSelection = this._dateAdapter.sameDateObject(value, oldSelection);

    this._datepickerService.updateSelectedValue(value);

    this._updateSelection(value);

    this._cdr.markForCheck();

    if (this._dateAdapter.isValidDateObject(value) && !sameValueAndOldSelection) {
      this._controlAccessorValue = value;
    }

    if (!sameValueAndOldSelection) {
      this._init();
    }
  }

  /** @hidden */
  registerOnChange(fn: (_: DateRange | Date | null) => void): void {
    this._onChangeFn = fn;
  }

  /** @hidden */
  registerOnTouched(fn: () => void): void {
    this._onTouched = fn;
  }

  // #endregion

  private _updateSelection(value?: DateRange | Date | null): void {
    if (!value) {
      this._datepickerService.updateSelection(
        this.isRangePicker ? new DateRange(null, null) : null,
      );
    } else {
      this._datepickerService.updateSelection(value);
    }
  }

  private _updateSelectedValue(): void {
    this._onChangeFn(this._selection);
    this._datepickerService.updateSelectedValue(this._selection);

    this.valueChanged.emit(this._selection);
  }

  private _setDatepickerVisibilityToDate(date?: Date | null): void {
    let showDate = date || this.startAt || new Date();
    let startOfNextMonth = this._datepickerService.getFirstDayOfNextMonth(showDate);

    if (!date && this.maxDate && this._dateAdapter.compareDate(showDate, this.maxDate) > 0) {
      showDate = this.maxDate;
      startOfNextMonth = this._datepickerService.getFirstDayOfNextMonth(showDate);
    }

    const source =
      this.isMobile ||
      this.displaySingleCalendar ||
      this.displayLastDisabledMonth ||
      !this.maxDate ||
      (this.maxDate && this._dateAdapter.compareDate(startOfNextMonth, this.maxDate) <= 0)
        ? 'left'
        : 'right';

    this._datepickerService.updateActiveDates(source, showDate);

    if (this.isMobile && showDate) {
      this._scrollToMonthYear(showDate.getMonth(), showDate.getFullYear());
    }
  }
}
