import { FocusableOption, FocusKeyManager } from '@angular/cdk/a11y';
import { NgFor, NgIf } from '@angular/common';
import {
  AfterContentInit,
  AfterViewInit,
  booleanAttribute,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  ElementRef,
  EventEmitter,
  HostListener,
  inject,
  Input,
  numberAttribute,
  OnChanges,
  OnInit,
  Output,
  QueryList,
  SimpleChanges,
  ViewChildren,
  ViewEncapsulation,
} from '@angular/core';
import { QDestroyService } from '@questrade/allspark-angular-components/core/services';
import {
  DOWN_ARROW,
  END,
  HOME,
  LEFT_ARROW,
  PAGE_DOWN,
  PAGE_UP,
  RIGHT_ARROW,
  TAB,
  UP_ARROW,
} from '@questrade/allspark-angular-components/core/utils';
import { takeUntil } from 'rxjs';
import { DateAdapter } from '../../date-adapter';
import { DatepickerService } from '../../datepicker.service';
import { DateRange } from '../../daterange';

import { QCalendarLocation } from '../../types/calendar-location.type';
import { QCalendarCell } from './calendar-cell';

export interface QCalendarUserEvent<D> {
  value: D;
  event: Event;
}

class FocusableElement implements FocusableOption {
  constructor(private _element: ElementRef) {}

  focus(): void {
    this._element.nativeElement.focus();
  }
}

@Component({
  selector: '[q-calendar-body]',
  templateUrl: './calendar-body.component.html',
  styleUrls: ['./calendar-body.component.scss'],
  host: {
    class: 'q-calendar-body',
    'aria-readonly': 'true',
  },
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  imports: [NgFor, NgIf],
  providers: [QDestroyService],
})
export class QCalendarBodyComponent implements OnInit, OnChanges, AfterViewInit, AfterContentInit {
  @Output() readonly selectedValueChange = new EventEmitter<QCalendarUserEvent<number>>();

  @Input({ transform: numberAttribute }) todayValue: number | null = null;
  @Input({ transform: numberAttribute }) numCols = 7;
  @Input({ transform: numberAttribute }) startValue: number | null = null;
  @Input({ transform: numberAttribute }) endValue: number | null = null;
  @Input({ transform: numberAttribute }) cellAspectRatio = 0.9475;
  @Input({ transform: booleanAttribute }) isRange = false;
  @Input() calendarLocation: QCalendarLocation = 'left';
  @Input() minDate: Date | null = null;
  @Input() maxDate: Date | null = null;
  @Input() disabledDates: Date[] = [];
  @Input() disableWeekends = false;

  @Input() get rows(): QCalendarCell[][] {
    return this._rows;
  }
  set rows(value: QCalendarCell[][]) {
    this._firstRowOffset = value.length ? this.numCols - value[0].length : 0;
    this._rows = value;
  }

  @ViewChildren('calendarCellButton', { read: ElementRef })
  calendarCellButtons!: QueryList<ElementRef>;

  @HostListener('keydown', ['$event']) onKeydown(event: KeyboardEvent): void {
    if (event.key === TAB) {
      if (this._focusApplied) {
        this._focusApplied = false;
        return;
      } else {
        this._applyFocus();
        event.preventDefault();
      }
    } else {
      this._handleKeydown(event);
    }
  }

  @HostListener('focusin') onFocusIn(): void {
    this._applyFocus();
  }

  _firstRowOffset = 0;
  _cellWidth = '';
  _cellPadding = '';
  _previewStart: number | null = null;
  _previewEnd: number | null = null;
  _selection: Date | DateRange | null = { start: null, end: null };

  private _rows: QCalendarCell[][] = [];
  private readonly _dateAdapter = inject(DateAdapter);
  private readonly _destroy$ = inject(QDestroyService);
  private readonly _datepickerService = inject(DatepickerService);
  private readonly _changeDetectorRef = inject(ChangeDetectorRef);
  private _keyManager: FocusKeyManager<FocusableOption> | null = null;
  private _focusedDate = new Date();
  private _focusApplied = false;

  ngOnInit(): void {
    this._datepickerService.preview$
      .pipe(takeUntil(this._destroy$))
      .subscribe((preview: DateRange) => {
        this._previewStart = preview.start?.getTime() ?? null;
        this._previewEnd = preview.end?.getTime() ?? null;
        this._changeDetectorRef.detectChanges();
      });

    this._datepickerService.selection$
      .pipe(takeUntil(this._destroy$))
      .subscribe((selection: Date | DateRange | null) => {
        this._selection = selection;
      });

    this._cellWidth = `${100 / this.numCols}%`;
    this._cellPadding = `${(50 * this.cellAspectRatio) / this.numCols}%`;
  }

  ngOnChanges(changes: SimpleChanges): void {
    const columnChanges = changes.numCols;
    const { rows, numCols } = this;

    if (changes.rows || columnChanges) {
      this._firstRowOffset = rows && rows[0].length ? numCols - rows[0].length : 0;
    }
  }

  ngAfterViewInit(): void {
    const focusableElements = this.calendarCellButtons.map(
      (button) => new FocusableElement(button),
    );
    this._keyManager = new FocusKeyManager<FocusableOption>(focusableElements).withWrap();
  }

  ngAfterContentInit(): void {
    this.subscribeToActiveDate();
  }

  private subscribeToActiveDate(): void {
    const activeDate$ =
      this.calendarLocation === 'left'
        ? this._datepickerService.activeDateFirstCalendar$
        : this._datepickerService.activeDateSecondCalendar$;

    activeDate$.pipe(takeUntil(this._destroy$)).subscribe((date) => this._updateFocusedDate(date));
  }

  private _updateFocusedDate(date: Date | null): void {
    if (!date) return;

    const firstDayOfMonth = new Date(date.getFullYear(), date.getMonth(), 1);
    const today = new Date();
    const isCurrentMonth =
      date.getMonth() === today.getMonth() && date.getFullYear() === today.getFullYear();

    this._focusedDate = isCurrentMonth ? today : this._getFirstEnabledDate(firstDayOfMonth, date);

    this._changeDetectorRef.markForCheck();
  }

  private _getFirstEnabledDate(firstDayOfMonth: Date, date: Date): Date {
    if (this._nextEnableDate(firstDayOfMonth) && !this._isDateDisabled(firstDayOfMonth)) {
      return firstDayOfMonth;
    }

    const daysInMonth = new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate();
    for (let day = 1; day <= daysInMonth; day++) {
      const activeDate = new Date(date.getFullYear(), date.getMonth(), day);
      if (this._nextEnableDate(activeDate) && !this._isDateDisabled(activeDate)) {
        return activeDate;
      }
    }

    return firstDayOfMonth;
  }

  private _applyFocus(): void {
    if (this._focusApplied || !this.calendarCellButtons) return;

    let focusedIndex = this.calendarCellButtons
      .toArray()
      .findIndex((button) => button.nativeElement.getAttribute('aria-selected') === 'true');

    if (focusedIndex === -1) {
      focusedIndex = this._getDayIndex(this._focusedDate) || 0;
    }

    if (focusedIndex >= 0 && focusedIndex < this.calendarCellButtons.length) {
      const cell = this._rows
        .flat()
        .find((cell) => cell.date && this._getDayIndex(cell.date) === focusedIndex);
      if (cell) {
        this._updateCellFocus(cell);
      }
      this._focusApplied = true;
    }
  }

  private _handleKeydown(event: KeyboardEvent): void {
    this._keyManager?.onKeydown(event);
    switch (event.key) {
      case UP_ARROW:
        this._moveFocusByDays(-this.numCols);
        break;

      case DOWN_ARROW:
        this._moveFocusByDays(this.numCols);
        break;

      case LEFT_ARROW:
        this._moveFocusByDays(-1);
        break;

      case RIGHT_ARROW:
        this._moveFocusByDays(1);
        break;

      case HOME:
        this._moveFocusToStartOfWeek();
        event.preventDefault();
        break;

      case END:
        this._moveFocusToEndOfWeek();
        event.preventDefault();
        break;

      case PAGE_UP:
        if (event.shiftKey) {
          this._moveFocusByYears(-1);
        } else {
          this._moveFocusByMonths(-1);
        }
        event.preventDefault();
        break;

      case PAGE_DOWN:
        if (event.shiftKey) {
          this._moveFocusByYears(1);
        } else {
          this._moveFocusByMonths(1);
        }
        event.preventDefault();
        break;
    }
  }

  private _updateFocusCalendarBody(newDate: Date): void {
    const newMonth = newDate.getMonth();
    const currentMonth = this._focusedDate.getMonth();
    const newYear = newDate.getFullYear();
    const currentYear = this._focusedDate.getFullYear();

    if (newMonth !== currentMonth || newYear !== currentYear) {
      const isNextMonth =
        newMonth > currentMonth || (newMonth === 0 && currentMonth === 11) || newYear > currentYear;
      const isPreviousMonth =
        newMonth < currentMonth || (newMonth === 11 && currentMonth === 0) || newYear < currentYear;

      if (isPreviousMonth || isNextMonth) {
        this._datepickerService.updateActiveDates(this.calendarLocation, newDate);
      }

      setTimeout(() => {
        const newIndex = this._getDayIndex(newDate);
        const newIndexValid = newIndex >= 0 && newIndex < this.calendarCellButtons.length;
        this._focusedDate = newDate;
        this._updateFocus(newIndexValid ? newIndex : 0);
        this._changeDetectorRef.detach();
        this._changeDetectorRef.detectChanges();
        this._changeDetectorRef.reattach();
      });
    } else {
      const newIndex = this._getDayIndex(newDate);
      if (newIndex >= 0 && newIndex < this.calendarCellButtons.length) {
        this._focusedDate = newDate;
        this._updateFocus(newIndex);
      }
    }
  }

  private _isDateDisabled(date: Date): boolean {
    if (!date) {
      return false;
    }

    const isDisabledDate = this.disabledDates.some(
      (disabledDate) =>
        disabledDate.getDate() === date.getDate() &&
        disabledDate.getMonth() === date.getMonth() &&
        disabledDate.getFullYear() === date.getFullYear(),
    );

    const isWeekend = this.disableWeekends && (date.getDay() === 0 || date.getDay() === 6);

    return isDisabledDate || isWeekend;
  }

  private _nextEnableDate(date: Date): boolean {
    const updateDate = (sourceDate: Date): void => {
      date.setDate(sourceDate.getDate());
      date.setMonth(sourceDate.getMonth());
      date.setFullYear(sourceDate.getFullYear());
    };

    if (this.maxDate && date > this.maxDate) {
      updateDate(this.maxDate);
    } else if (this.minDate && date < this.minDate) {
      updateDate(this.minDate);
    }

    return true;
  }

  private _findNextEnabledDate(
    date: Date,
    offset: number,
    isDisabled: (date: Date) => boolean,
  ): Date {
    while (isDisabled(date)) {
      date.setDate(date.getDate() + offset);
    }
    return date;
  }

  private _moveFocusByDays(days: number): void {
    const currentDate = this._focusedDate;
    let newDate = new Date(currentDate);

    newDate.setDate(newDate.getDate() + days);

    const offset =
      Math.abs(days) === 1 ? (days > 0 ? 1 : -1) : days > 0 ? this.numCols : -this.numCols;
    newDate = this._findNextEnabledDate(newDate, offset, this._isDateDisabled.bind(this));

    this._nextEnableDate(newDate);
    this._updateFocusCalendarBody(newDate);
  }

  private _moveFocusByMonths(numMonths: number): void {
    const currentDate = this._focusedDate;
    const isPrev = numMonths < 0;
    const numYears = Math.trunc(Math.abs(numMonths) / 12);
    numMonths = Math.abs(numMonths) % 12;

    const newYear = isPrev
      ? currentDate.getFullYear() - numYears
      : currentDate.getFullYear() + numYears;

    const newMonth = isPrev
      ? currentDate.getMonth() - numMonths
      : currentDate.getMonth() + numMonths;

    let newDate = new Date(newYear, newMonth, 1);

    const daysInMonth = this._dateAdapter.getNumDaysInMonth(newDate);

    if (currentDate.getDate() > daysInMonth) {
      newDate.setDate(daysInMonth);
    } else {
      newDate.setDate(currentDate.getDate());
    }

    newDate = this._findNextEnabledDate(newDate, isPrev ? 1 : -1, this._isDateDisabled.bind(this));

    this._nextEnableDate(newDate);
    this._updateFocusCalendarBody(newDate);
  }

  private _moveFocusByYears(years: number): void {
    const currentDate = this._focusedDate;
    let newDate = new Date(currentDate);
    const targetYear = newDate.getFullYear() + years;
    const targetDaysInMonth = this._dateAdapter.getNumDaysInMonth(
      new Date(targetYear, newDate.getMonth(), 1),
    );

    if (currentDate.getDate() > targetDaysInMonth) {
      newDate.setDate(targetDaysInMonth);
    }

    newDate.setFullYear(targetYear);

    newDate = this._findNextEnabledDate(
      newDate,
      years > 0 ? -1 : 1,
      this._isDateDisabled.bind(this),
    );

    this._nextEnableDate(newDate);
    this._updateFocusCalendarBody(newDate);
  }

  private _moveFocusToStartOfWeek(): void {
    const currentDate = this._focusedDate;
    let newDate = new Date(currentDate);

    newDate.setDate(newDate.getDate() - newDate.getDay());

    newDate = this._findNextEnabledDate(newDate, 1, this._isDateDisabled.bind(this));

    this._nextEnableDate(newDate);
    this._updateFocusCalendarBody(newDate);
  }

  private _moveFocusToEndOfWeek(): void {
    const currentDate = this._focusedDate;
    let newDate = new Date(currentDate);

    newDate.setDate(newDate.getDate() + (6 - newDate.getDay()));

    newDate = this._findNextEnabledDate(newDate, -1, this._isDateDisabled.bind(this));

    this._nextEnableDate(newDate);
    this._updateFocusCalendarBody(newDate);
  }

  private _updateCellFocus(cell: QCalendarCell): void {
    const newIndex = cell.date ? this._getDayIndex(cell.date) : -1;
    if (cell.date) {
      this._focusedDate = cell.date;
    }
    this._updateFocus(newIndex);
  }

  private _updateFocus(newIndex: number): void {
    if (newIndex >= 0 && newIndex < this.calendarCellButtons.length) {
      const targetButton = this.calendarCellButtons.toArray()[newIndex];
      this._keyManager?.setActiveItem(newIndex);
      targetButton.nativeElement.focus();
    }
  }

  getTabIndex(item: QCalendarCell): number {
    if (!item.date) return 0;

    const focusedDay = this._focusedDate.getDate();
    const itemDay = item.date.getDate();
    return itemDay === focusedDay ? 0 : -1;
  }

  private _getDayIndex(date: Date): number {
    const day = date.getDate();
    const cellbutton = this.calendarCellButtons.find(
      (button) => parseInt(button.nativeElement.textContent.trim(), 10) === day,
    );
    return cellbutton ? this.calendarCellButtons.toArray().indexOf(cellbutton) : 0;
  }

  onMouseEnter(cell: QCalendarCell): void {
    if (cell && this.isRange) {
      const newPreviewRange = this._createPreview(cell.date ?? null, this._selection as DateRange);

      this._datepickerService.updatePreview(newPreviewRange);
    }
  }

  onMouseLeave = (): void => {
    if (this._previewEnd !== null && this.isRange) {
      this._datepickerService.updatePreview(new DateRange(null, null));
    }
  };

  _isSelected(value: number): boolean {
    const valueDate = new Date(value);
    const startValueDate = new Date(this.startValue ?? 0);
    const endValueDate = new Date(this.endValue ?? 0);

    return (
      this._dateAdapter.sameDate(valueDate, startValueDate) ||
      this._dateAdapter.sameDate(valueDate, endValueDate)
    );
  }

  _isYearSelected(year: number): boolean {
    return year === this.startValue && year === this.endValue;
  }

  _cellClicked(cell: QCalendarCell, event: MouseEvent): void {
    if (cell.enabled) {
      this.selectedValueChange.emit({ value: cell.value, event });
      this._updateCellFocus(cell);
    }
  }

  _showHighlightEnd(item: QCalendarCell): boolean | undefined {
    return (
      item.date &&
      (item.date.getDay() === 6 || item.value === this._dateAdapter.getNumDaysInMonth(item.date))
    );
  }

  _isRangeStart(value: Date | undefined): boolean {
    return (value && this._isStart(value.getTime(), this.startValue, this.endValue)) || false;
  }

  _isRangeEnd(value: Date | undefined): boolean {
    return (value && this._isEnd(value.getTime(), this.startValue, this.endValue)) || false;
  }

  _isInRange(value: number | undefined): boolean {
    return value ? this._isDateInRange(value, this.startValue, this.endValue) : false;
  }

  _isPreviewStart(value: Date | undefined): boolean {
    return (value && this._isStart(value.getTime(), this._previewStart, this._previewEnd)) || false;
  }

  _isPreviewEnd(value: Date | undefined): boolean {
    return (value && this._isEnd(value.getTime(), this._previewStart, this._previewEnd)) || false;
  }

  _isInPreview(value: number | undefined): boolean {
    return !!value && this._isDateInRange(value, this._previewStart, this._previewEnd);
  }

  _isCalendarItemSelected(cell: QCalendarCell): boolean {
    if (!cell.date) {
      return this._isYearSelected(cell.value);
    }
    return this._isSelected(cell.date.getTime());
  }

  private _isDateInRange(value: number | null, start: number | null, end: number | null): boolean {
    if (!value || !start || !end) return false;

    const valueDate = new Date(value);
    const startValueDate = new Date(start);
    const endValueDate = new Date(end);

    return (
      this.isRange &&
      start !== null &&
      end !== null &&
      start !== end &&
      this._dateAdapter.compareDate(valueDate, startValueDate) >= 0 &&
      this._dateAdapter.compareDate(valueDate, endValueDate) <= 0
    );
  }

  private _isStart(value: number | null, start: number | null, end: number | null): boolean {
    if (!value || !start || !end) return false;

    const valueDate = new Date(value);
    const startValueDate = new Date(start);

    return (
      end !== null &&
      start !== end &&
      value < end &&
      this._dateAdapter.sameDate(valueDate, startValueDate)
    );
  }

  private _isEnd(value: number | null, start: number | null, end: number | null): boolean {
    if (!value || !start || !end) return false;

    const valueDate = new Date(value);
    const endValueDate = new Date(end);

    return (
      start !== null &&
      start !== end &&
      value >= start &&
      this._dateAdapter.sameDate(valueDate, endValueDate)
    );
  }

  private _createPreview(activeDate: Date | null, selection: DateRange): DateRange {
    let start: Date | null = null;
    let end: Date | null = null;

    if (selection.start && !selection.end && activeDate) {
      start = selection.start;
      end = activeDate;
    }

    return new DateRange(start, end);
  }
}
