import { AsyncPipe } from '@angular/common';
import {
  AfterContentInit,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  EventEmitter,
  HostBinding,
  Input,
  Output,
  ViewChild,
  ViewEncapsulation,
  booleanAttribute,
  inject,
} from '@angular/core';
import { QDestroyService } from '@questrade/allspark-angular-components/core/services';
import { BehaviorSubject, takeUntil } from 'rxjs';
import { DateAdapter } from '../date-adapter';
import { DatepickerService } from '../datepicker.service';
import { DateRange } from '../daterange';
import { QCalendarLocation } from '../types/calendar-location.type';
import { QCalendarView } from '../types/calendar-view.type';
import { QCalendarUserEvent } from './calendar-body/calendar-body.component';
import { QCalendarHeaderComponent } from './calendar-header/calendar-header.component';
import { QMonthViewComponent } from './month-view/month-view.component';

export const BOX_SHADOW_CLASSES = {
  TOP: 'inset 0 8px 8px -8px rgba(0, 0, 0, 0.08)',
  BOTTOM: 'inset 0 -8px 8px -8px rgba(0, 0, 0, 0.08)',
};

let nextUniqueId = 0;

@Component({
  selector: 'q-calendar',
  templateUrl: './calendar.component.html',
  styleUrls: ['./calendar.component.scss'],
  imports: [AsyncPipe, QCalendarHeaderComponent, QMonthViewComponent],
  providers: [QDestroyService],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
})
export class QCalendarComponent implements AfterContentInit {
  @Output() readonly selectedChange = new EventEmitter<Date | null>();
  @Output() readonly _userSelection = new EventEmitter<QCalendarUserEvent<Date | null>>();
  @Output() readonly yearSelected = new EventEmitter<Date>();
  @Output() readonly monthSelected = new EventEmitter<Date>();
  @Output() readonly monthChangedByArrow = new EventEmitter<number>();
  @Output() readonly viewChanged = new EventEmitter<QCalendarView>(true);

  @Input() calendarLocation: QCalendarLocation = 'left';
  @Input({ transform: booleanAttribute }) isMobile = false;
  @Input({ transform: booleanAttribute }) displaySingleCalendar = false;
  @Input() selected: DateRange | Date | null = null;
  @Input() minDate: Date | null = null;
  @Input() maxDate: Date | null = null;
  @Input() previousMonthButtonAriaLabel = '';
  @Input() nextMonthButtonAriaLabel = '';

  @Input() get currentView(): QCalendarView {
    return this._currentView;
  }
  set currentView(value: QCalendarView) {
    if (this._currentView !== value) {
      this._currentView = value;
      this.viewChanged.emit(value);
    }
  }

  @Input() get activeDate(): Date {
    return this._activeDate;
  }
  set activeDate(value: Date) {
    this._activeDate = value;
    this._cdr.markForCheck();
  }

  @HostBinding('class') hostClass = 'q-calendar';

  @ViewChild(QCalendarHeaderComponent) calendarHeaderComponentRef!: QCalendarHeaderComponent;

  multiYearViewId = `multi-year-view-header-${nextUniqueId++}`;
  monthViewId = `month-view-header-${nextUniqueId++}`;

  readonly _datepickerService = inject(DatepickerService);
  private _boxShadowClass = 'none';
  readonly _boxShadowSubject$ = new BehaviorSubject(this._boxShadowClass);
  boxShadow$ = this._boxShadowSubject$.asObservable();

  private _currentView: QCalendarView = 'month';
  private _activeDate!: Date;
  private readonly _destroy$ = inject(QDestroyService);
  private readonly _dateAdapter = inject(DateAdapter);
  private readonly _cdr = inject(ChangeDetectorRef);

  ngAfterContentInit(): void {
    const activeDateObservable =
      this.calendarLocation === 'left'
        ? this._datepickerService.activeDateFirstCalendar$
        : this._datepickerService.activeDateSecondCalendar$;

    activeDateObservable.pipe(takeUntil(this._destroy$)).subscribe((date: Date | null) => {
      this.activeDate = date as Date;
    });
  }

  _getSelectedYear(): number | null {
    if (this.selected instanceof DateRange) {
      return null;
    }

    return this.selected?.getFullYear() || null;
  }

  _changeMonth(delta: number): void {
    this.monthChangedByArrow.emit(delta);
  }

  _dateSelected(event: QCalendarUserEvent<Date | null>): void {
    const date = event.value;

    if (
      this.selected instanceof DateRange ||
      (date && !this._dateAdapter.sameDate(date, this.selected))
    ) {
      this.selectedChange.emit(date);
    }
  }

  _yearSelectedInMultiYearView(year: number): void {
    const yearAsDate = new Date(year, 6, 1);

    this.yearSelected.emit(yearAsDate);
    this._updateActiveDates(yearAsDate);
  }

  _onMonthSelected(month: Date): void {
    this.monthSelected.emit(month);
    this._updateActiveDates(month);
  }

  _onYearSelected(year: Date): void {
    this.yearSelected.emit(year);
    this._updateActiveDates(year);
  }

  _updateActiveDates(date: Date): void {
    this._datepickerService.updateActiveDates(this.calendarLocation, date);
  }

  _calculateBoxShadows(el: EventTarget | null): void {
    if (!el) return;

    const element = el as HTMLElement;
    const showTopShadow = element.scrollTop > 0;
    const scrolledToBottom = element.scrollHeight - element.scrollTop === element.clientHeight;
    const showBottomShadow = element.scrollHeight > element.clientHeight && !scrolledToBottom;
    const showTopAndBottomShadow = showTopShadow && showBottomShadow;

    if (showTopAndBottomShadow) {
      this._boxShadowClass = `${BOX_SHADOW_CLASSES.TOP}, ${BOX_SHADOW_CLASSES.BOTTOM}`;
    } else {
      this._boxShadowClass = showTopShadow
        ? BOX_SHADOW_CLASSES.TOP
        : showBottomShadow
          ? BOX_SHADOW_CLASSES.BOTTOM
          : 'none';
    }

    this._boxShadowSubject$.next(this._boxShadowClass);
  }

  _setCalendarHeaderComponentFocus(): void {
    this.calendarHeaderComponentRef?._setFocus();
  }
}
