import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable, Subject } from 'rxjs';
import { DateRange } from './daterange';
import { QCalendarLocation } from './types/calendar-location.type';

@Injectable()
export class DatepickerService {
  private _preview = new Subject<DateRange>();
  private _selectedValue = new BehaviorSubject<Date | DateRange | null>(null);
  private _selection = new BehaviorSubject<Date | DateRange | null>(null);
  private _activeDateFirstCalendar = new BehaviorSubject<Date | null>(null);
  private _activeDateSecondCalendar = new BehaviorSubject<Date | null>(null);
  private _disableWeekends = new BehaviorSubject<boolean>(false);
  private _disabledDates = new BehaviorSubject<Date[]>([]);

  preview$: Observable<DateRange> = this._preview.asObservable();
  selectedValue$: Observable<Date | DateRange | null> = this._selectedValue.asObservable();
  selection$: Observable<Date | DateRange | null> = this._selection.asObservable();
  activeDateFirstCalendar$: Observable<Date | null> = this._activeDateFirstCalendar.asObservable();
  activeDateSecondCalendar$: Observable<Date | null> =
    this._activeDateSecondCalendar.asObservable();
  disableWeekends$ = this._disableWeekends.asObservable();
  disabledDates$ = this._disabledDates.asObservable();

  updateDisableWeekends(value: boolean): void {
    this._disableWeekends.next(value);
  }

  updateDisabledDates(datesDisabled: Date[]): void {
    this._disabledDates.next(datesDisabled);
  }

  updatePreview(value: DateRange): void {
    this._preview.next(value);
  }

  updateSelection(value: Date | DateRange | null): void {
    this._selection.next(value);
  }

  updateSelectedValue(value: Date | DateRange | null): void {
    this._selectedValue.next(value);
  }

  updateActiveDates(sourceCalendarLocation: QCalendarLocation, date: Date): void {
    if (sourceCalendarLocation === 'left') {
      this._activeDateFirstCalendar.next(date);
      this._activeDateSecondCalendar.next(this._createDateWithDelta(date, 1));
    } else if (sourceCalendarLocation === 'right') {
      this._activeDateFirstCalendar.next(this._createDateWithDelta(date, -1));
      this._activeDateSecondCalendar.next(date);
    }
  }

  shiftActiveDatesByDelta(delta: number): void {
    this._activeDateFirstCalendar.next(
      this._createDateWithDelta(this.activeDateFirstCalendar, delta),
    );
    this._activeDateSecondCalendar.next(
      this._createDateWithDelta(this.activeDateSecondCalendar, delta),
    );
  }

  isValidSelection(isRange: boolean): boolean {
    const isValidDate = (d: Date): boolean => !isNaN(d?.valueOf()) && d instanceof Date;

    if (isRange) {
      const { start, end } = this.selection as DateRange;
      if (!start || !end) return false;

      return isValidDate(start) && isValidDate(end);
    } else {
      return isValidDate(this.selection as Date);
    }
  }

  getFirstDayOfNextMonth(date: Date): Date {
    return new Date(date.getFullYear(), date.getMonth() + 1, 1);
  }

  get selectedValue(): Date | DateRange | null {
    return this._selectedValue.getValue();
  }

  get selection(): Date | DateRange | null {
    return this._selection.getValue();
  }

  get activeDateFirstCalendar(): Date | null {
    return this._activeDateFirstCalendar.getValue();
  }

  get activeDateSecondCalendar(): Date | null {
    return this._activeDateSecondCalendar.getValue();
  }

  private _getLastDayOfMonth(date: Date): number {
    const newDate = new Date(date.getFullYear(), date.getMonth() + 1, 0);

    return newDate.getDate();
  }

  private _createDateWithDelta(originDate: Date | null, delta: number): Date | null {
    if (!originDate) return null;

    const newDate = new Date(originDate.getFullYear(), originDate.getMonth() + delta, 1);
    const lastDayOfNewMonth = this._getLastDayOfMonth(newDate);

    if (originDate.getDate() > lastDayOfNewMonth) {
      newDate.setDate(lastDayOfNewMonth);
    } else {
      newDate.setDate(originDate.getDate());
    }

    return newDate;
  }
}
