import { Injectable, inject } from '@angular/core';
import { TranslocoService } from '@jsverse/transloco';
import { range } from '@questrade/allspark-angular-components/core/utils';
import { DateRange } from './daterange';

@Injectable({
  providedIn: 'root',
})
export class DateAdapter {
  private readonly _translocoService = inject(TranslocoService);
  private _format(dtf: Intl.DateTimeFormat, date: Date): string {
    const d = new Date();

    d.setUTCFullYear(date.getFullYear(), date.getMonth(), date.getDate());
    d.setUTCHours(date.getHours(), date.getMinutes(), date.getSeconds(), date.getMilliseconds());

    return dtf.format(d);
  }

  sameDate(first: Date | null, second: Date | null): boolean {
    if (first && second) {
      const firstValid = this.isValid(first);
      const secondValid = this.isValid(second);

      if (firstValid && secondValid) {
        return !this.compareDate(first, second);
      }

      return firstValid === secondValid;
    }

    return first === second;
  }

  sameDateObject(first: Date | DateRange | null, second: Date | DateRange | null): boolean {
    if (first instanceof Date && second instanceof Date) {
      return this.sameDate(first, second);
    } else if (first instanceof DateRange && second instanceof DateRange) {
      return this.sameDate(first.start, second.start) && this.sameDate(first.end, second.end);
    }

    return false;
  }

  isValid(date: Date | null): boolean {
    return date ? date && !isNaN(date.getTime()) : false;
  }

  isValidDateObject(date: Date | DateRange): boolean {
    if (date instanceof Date) {
      return this.isValid(date);
    } else if (date instanceof DateRange && date.start && date.end) {
      return this.isValid(date.start) && this.isValid(date.end);
    }

    return false;
  }

  compareDate(first: Date, second: Date): number {
    return (
      first.getFullYear() - second.getFullYear() ||
      first.getMonth() - second.getMonth() ||
      first.getDate() - second.getDate()
    );
  }

  getNumDaysInMonth(date: Date): number {
    const d = new Date(date.getFullYear(), date.getMonth() + 1, 0);

    return d.getDate();
  }

  clampDate(date: Date, min?: Date | null, max?: Date | null): Date {
    if (min && this.compareDate(date, min) < 0) {
      return min;
    }

    if (max && this.compareDate(date, max) > 0) {
      return max;
    }

    return date;
  }

  isDateInstance(obj: unknown): boolean {
    return obj instanceof Date;
  }

  getMonthName(date: Date, style: 'long' | 'short' | 'narrow' = 'long'): string {
    const activeLanguage = this._translocoService.getActiveLang();
    const dtf = new Intl.DateTimeFormat(activeLanguage, { month: style, timeZone: 'utc' });

    return this._format(dtf, date);
  }

  getMonthNames(style: 'long' | 'short' | 'narrow'): string[] {
    const activeLanguage = this._translocoService.getActiveLang();
    const dtf = new Intl.DateTimeFormat(activeLanguage, { month: style, timeZone: 'utc' });

    return range(12, (i) => this._format(dtf, new Date(2017, i, 1))) as string[];
  }

  getYearName(date: Date): string {
    const activeLanguage = this._translocoService.getActiveLang();
    const dtf = new Intl.DateTimeFormat(activeLanguage, { year: 'numeric', timeZone: 'utc' });

    return this._format(dtf, date);
  }

  getMonthsInRange(minDate: Date, maxDate: Date): { month: number; year: number }[] {
    const months: { month: number; year: number }[] = [];
    let year = minDate.getFullYear();
    let month = minDate.getMonth();

    while (
      year < maxDate.getFullYear() ||
      (year === maxDate.getFullYear() && month <= maxDate.getMonth())
    ) {
      months.push({ month, year });
      month++;
      if (month > 11) {
        month = 0;
        year++;
      }
    }
    return months;
  }
}
