import { NgSwitch, NgSwitchCase, TitleCasePipe } from '@angular/common';
import {
  booleanAttribute,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  ElementRef,
  EventEmitter,
  inject,
  Input,
  OnChanges,
  Output,
  SimpleChanges,
  ViewChild,
  ViewEncapsulation,
} from '@angular/core';
import { TranslocoModule } from '@jsverse/transloco';
import { QChipComponent } from '@questrade/allspark-angular-components/chip';
import { isPresent } from '@questrade/allspark-angular-components/core/utils';
import {
  QDropmenuComponent,
  QDropmenuOriginDirective,
  QDropmenuSelectionChange,
} from '@questrade/allspark-angular-components/dropmenu';
import { QIconRegistryService } from '@questrade/allspark-angular-components/icon';
import { QInteractiveIconComponent } from '@questrade/allspark-angular-components/interactive-icon';
import {
  ALLSPARK_SCOPE,
  MISSING_KEY_HANDLER,
} from '@questrade/allspark-angular-components/transloco';
import { chevronLeft, chevronRight } from '@questrade/allspark-icons/icons';
import { DateAdapter } from '../../date-adapter';
import { QCalendarLocation } from '../../types/calendar-location.type';
import { QCalendarView } from '../../types/calendar-view.type';

@Component({
  selector: 'q-calendar-header',
  imports: [
    NgSwitch,
    NgSwitchCase,
    TranslocoModule,
    TitleCasePipe,
    QChipComponent,
    QInteractiveIconComponent,
    QDropmenuComponent,
    QDropmenuOriginDirective,
  ],
  providers: [MISSING_KEY_HANDLER, ALLSPARK_SCOPE],
  templateUrl: './calendar-header.component.html',
  styleUrls: ['./calendar-header.component.scss'],
  encapsulation: ViewEncapsulation.None,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class QCalendarHeaderComponent implements OnChanges {
  @Output() readonly previousClicked = new EventEmitter<Event>();
  @Output() readonly nextClicked = new EventEmitter<Event>();
  @Output() readonly monthSelected = new EventEmitter<Date>();
  @Output() readonly yearSelected = new EventEmitter<Date>();

  @Input({ transform: booleanAttribute }) isMobile = false;
  @Input({ transform: booleanAttribute }) displaySingleCalendar = false;
  @Input() currentView: QCalendarView = 'month';
  @Input() calendarLocation: QCalendarLocation = 'left';
  @Input() activeDate: Date | null = null;
  @Input() minDate: Date | null = null;
  @Input() maxDate: Date | null = null;
  @Input() previousMonthButtonAriaLabel = '';
  @Input() nextMonthButtonAriaLabel = '';
  @Input() multiYearViewId = '';
  @Input() monthViewId = '';

  @ViewChild('calendarHeaderRef') calendarHeaderRef!: ElementRef<HTMLElement>;

  private _yearOptions: { label: string; value: number; disabled: boolean }[] = [];
  private _monthNames: { label: string; value: number; disabled: boolean }[] = [];
  private _dateAdapter = inject(DateAdapter);
  private _iconRegistry = inject(QIconRegistryService);
  private _cdr = inject(ChangeDetectorRef);

  constructor() {
    this._iconRegistry.registerIcons([chevronLeft, chevronRight]);
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['activeDate'] || changes['minDate'] || changes['maxDate']) {
      this._setMonthNames();
    }

    if (changes['minDate'] || changes['maxDate']) {
      this._setYearOptions();
    }
  }

  _isYearAndMonthSameOrAfterMaxDate(): boolean {
    if (this.maxDate && this.activeDate) {
      const maxYear = this.maxDate.getFullYear();
      const maxMonth = this.maxDate.getMonth();
      const activeYear = this.activeDate.getFullYear();
      const activeMonth = this.activeDate.getMonth();

      return activeYear > maxYear || (activeYear === maxYear && activeMonth >= maxMonth);
    }

    return false;
  }

  _isYearAndMonthSameOrBeforeMinDate(): boolean {
    if (this.minDate && this.activeDate) {
      const minYear = this.minDate.getFullYear();
      const minMonth = this.minDate.getMonth();
      const activeYear = this.activeDate.getFullYear();
      const activeMonth = this.activeDate.getMonth();

      return activeYear < minYear || (activeYear === minYear && activeMonth <= minMonth);
    }

    return false;
  }

  _onPreviousClicked(event: Event): void {
    if (this._isYearAndMonthSameOrBeforeMinDate()) return;

    this.previousClicked.emit(event);
  }

  _onNextClicked(event: Event): void {
    if (this._isYearAndMonthSameOrAfterMaxDate()) return;

    this.nextClicked.emit(event);
  }

  _setFocus(): void {
    this.calendarHeaderRef?.nativeElement?.focus();
  }

  private _setMonthNames = (): void => {
    const year = this.activeDate?.getFullYear() ?? new Date().getFullYear();
    const minMonth =
      this.minDate && this.minDate.getFullYear() === year ? this.minDate.getMonth() : 0;
    const maxMonth =
      this.maxDate && this.maxDate.getFullYear() === year ? this.maxDate.getMonth() : 11;

    const monthNames = this._dateAdapter.getMonthNames('long');
    this._monthNames = monthNames.map((name, i) => ({
      label: name,
      value: i,
      disabled: i < minMonth || i > maxMonth,
    }));

    this._cdr.markForCheck();
  };

  get monthNames(): { label: string; value: number; disabled: boolean }[] {
    return this._monthNames;
  }

  get selectedMonthLabel(): string {
    const monthIndex = this.activeDate?.getMonth() ?? 0;
    return this.monthNames[monthIndex]?.label ?? '';
  }

  get yearOptions(): { label: string; value: number; disabled: boolean }[] {
    return this._yearOptions;
  }

  private _generateYearOptions(
    minYear?: number,
    maxYear?: number,
  ): { label: string; value: number; disabled: boolean }[] {
    const currentYear = new Date().getFullYear();
    const endYear = typeof maxYear === 'number' && maxYear > currentYear ? maxYear : currentYear;
    const startYear = endYear - 99;

    return Array.from({ length: endYear - startYear + 1 }, (_, i) => {
      const year = startYear + i;
      return {
        label: String(year),
        value: year,
        disabled: (isPresent(minYear) && year < minYear) || (isPresent(maxYear) && year > maxYear),
      };
    });
  }

  private _setYearOptions(): void {
    const minYear = this.minDate?.getFullYear();
    const maxYear = this.maxDate?.getFullYear();

    this._yearOptions = this._generateYearOptions(minYear, maxYear);
    this._cdr.markForCheck();
  }

  get showChevronLeft(): boolean {
    return this.displaySingleCalendar || (!this.isMobile && this.calendarLocation === 'left');
  }

  get showChevronRight(): boolean {
    return this.displaySingleCalendar || (!this.isMobile && this.calendarLocation === 'right');
  }

  get activeMonth(): number {
    return this.activeDate ? this.activeDate.getMonth() : 0;
  }

  get activeYear(): number {
    return this.activeDate ? this.activeDate.getFullYear() : 0;
  }

  onMonthSelectionChange(event: QDropmenuSelectionChange<number>): void {
    if (!this.activeDate) return;
    const month = event.option.value;
    if (!isPresent(month)) {
      return;
    }

    const selectedMonth = new Date(this.activeDate.getFullYear(), month, 1);
    const daysInMonth = this._dateAdapter.getNumDaysInMonth(selectedMonth);
    const selectedDate = new Date(
      this.activeDate.getFullYear(),
      month,
      Math.min(this.activeDate.getDate(), daysInMonth),
    );

    this.monthSelected.emit(selectedDate);
  }

  onYearSelectionChange(event: QDropmenuSelectionChange<number>): void {
    if (!this.activeDate) return;

    const year = event.option.value;
    if (typeof year === 'number') {
      const month = this.activeDate.getMonth();
      const day = this.activeDate.getDate();
      const daysInMonth = this._dateAdapter.getNumDaysInMonth(new Date(year, month, 1));
      const selectedDate = new Date(year, month, Math.min(day, daysInMonth));
      this.yearSelected.emit(selectedDate);
    }
  }
}
